def loan(P, annual, n):
    r = annual / 12
    pmt = P * r / (1 - (1 + r) ** -n)
    return round(pmt, 2), round(pmt * n - P, 2)
print('7% 3yr:', loan(10000, 0.07, 36))
print('5.5% 5yr:', loan(10000, 0.055, 60))

def pmt(P, annual, n):
    r = annual / 12
    return P * r / (1 - (1 + r) ** -n)
a = pmt(200000, 0.0625, 360)
b = pmt(200000, 0.0675, 360)
print(round(a, 2), round(b, 2), round(b - a, 2))
